describe('Modal Focus Trapping', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should trap focus inside the modal when open', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify focus is on the first interactive element inside the modal
    cy.get('[data-testid="modal-input"]').should('have.focus');

    // Tab through modal elements
    cy.get('[data-testid="modal-input"]').tab();
    cy.get('[data-testid="modal-button"]').should('have.focus');

    // Tab again - focus should wrap back to the first element
    cy.get('[data-testid="modal-button"]').tab();
    cy.get('[data-testid="modal-input"]').should('have.focus');

    // Tab again - focus should wrap to the last element
    cy.get('[data-testid="modal-input"]').tab();
    cy.get('[data-testid="modal-button"]').should('have.focus');
  });

  it('should trap focus when modal is closed', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Close the modal using the close button
    cy.get('[data-testid="modal-close-button"]').click();

    // Verify modal is no longer visible
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify focus returns to the element that opened the modal
    cy.get('[data-testid="open-modal-button"]').should('have.focus');

    // Verify focus is not trapped in the background
    cy.get('[data-testid="modal-input"]').should('not.exist');
  });
});
